package io.storyspace.api;
import io.storyspace.accounts.Account;import io.storyspace.api.ApiDtos.*;import io.storyspace.catalog.*;import io.storyspace.library.*;import io.storyspace.service.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.orm.ObjectOptimisticLockingFailureException;import org.springframework.http.ResponseEntity;import org.springframework.transaction.annotation.Transactional;import jakarta.validation.Valid;import java.time.Instant;import java.util.List;import java.util.UUID;
@RestController @RequestMapping("/api/library")public class LibraryController {private final CurrentAccount current;private final LibraryRepository library;private final LibraryDeletionRepository deletions;private final TitleRepository titles;private final RecommendationService rec;
 public LibraryController(CurrentAccount c,LibraryRepository l,LibraryDeletionRepository d,TitleRepository t,RecommendationService r){current=c;library=l;deletions=d;titles=t;rec=r;}
 @ExceptionHandler(ObjectOptimisticLockingFailureException.class) public ResponseEntity<String> concurrentWrite(){return ResponseEntity.status(HttpStatus.CONFLICT).body("A concurrent library update won; refresh and retry the latest intent");}
 private LibraryDto dto(LibraryItem item){return new LibraryDto(rec.dto(item.getTitle()),item.getState(),item.getProgressPercent(),item.getUserRating(),item.getResumePositionSeconds(),item.getDurationSeconds(),item.getLastPlayedAt(),item.getUpdatedAt());}
 @GetMapping public List<LibraryDto> list(){return library.findByAccountId(current.require().getId()).stream().map(this::dto).toList();}
 @GetMapping("/deletions") public List<LibraryDeletionDto> listDeletions(){return deletions.findByAccount_Id(current.require().getId()).stream().map(d->new LibraryDeletionDto(d.getTitle().getId(),d.getUpdatedAt())).toList();}
 @PutMapping("/{titleId}") @Transactional public LibraryDto save(@PathVariable UUID titleId,@RequestBody(required=false) LibraryMutationRequest mutation){Account a=current.require();Instant changedAt=mutation==null||mutation.updatedAt()==null?Instant.now():mutation.updatedAt();LibraryDeletion tombstone=deletions.findByAccount_IdAndTitle_Id(a.getId(),titleId).orElse(null);if(tombstone!=null&&tombstone.getUpdatedAt().isAfter(changedAt))throw new ResponseStatusException(HttpStatus.CONFLICT,"A newer deletion exists for this title");Title t=titles.findById(titleId).orElseThrow(()->new IllegalArgumentException("Title not found"));LibraryItem i=library.findByAccountIdAndTitleId(a.getId(),t.getId()).orElse(null);if(i!=null&&i.getUpdatedAt().isAfter(changedAt))throw new ResponseStatusException(HttpStatus.CONFLICT,"A newer library update exists for this title");if(i==null)i=new LibraryItem(a,t);i.setState("WATCHLIST");i.setUpdatedAt(changedAt);LibraryItem saved=library.save(i);if(tombstone!=null)deletions.delete(tombstone);return dto(saved);}
 @DeleteMapping("/{titleId}") @Transactional public void remove(@PathVariable UUID titleId,@RequestBody(required=false) LibraryMutationRequest mutation){Account a=current.require();Instant changedAt=mutation==null||mutation.updatedAt()==null?Instant.now():mutation.updatedAt();LibraryItem existing=library.findByAccountIdAndTitleId(a.getId(),titleId).orElse(null);if(existing!=null&&existing.getUpdatedAt().isAfter(changedAt))throw new ResponseStatusException(HttpStatus.CONFLICT,"A newer library update exists for this title");Title t=titles.findById(titleId).orElseThrow(()->new IllegalArgumentException("Title not found"));LibraryDeletion tombstone=deletions.findByAccount_IdAndTitle_Id(a.getId(),titleId).orElse(null);if(tombstone!=null&&tombstone.getUpdatedAt().isAfter(changedAt))throw new ResponseStatusException(HttpStatus.CONFLICT,"A newer deletion exists for this title");if(existing!=null)library.delete(existing);if(tombstone==null)tombstone=new LibraryDeletion(a,t,changedAt);tombstone.setUpdatedAt(changedAt);deletions.save(tombstone);}
 @PatchMapping("/{titleId}/progress")public LibraryDto progress(@PathVariable UUID titleId,@Valid @RequestBody ProgressRequest r){LibraryItem i=library.findByAccountIdAndTitleId(current.require().getId(),titleId).orElseThrow(()->new IllegalArgumentException("Add this title to your library first"));if(r.currentTime()!=null||r.duration()!=null){if(r.currentTime()==null||r.duration()==null)throw new IllegalArgumentException("Playback currentTime and duration must be supplied together");i.setPlaybackPosition(r.currentTime(),r.duration());}else{i.setProgressPercent(r.progressPercent());}return dto(library.save(i));}
 @PatchMapping("/{titleId}/rating")public LibraryDto rate(@PathVariable UUID titleId,@Valid @RequestBody RatingRequest r){LibraryItem i=library.findByAccountIdAndTitleId(current.require().getId(),titleId).orElseThrow(()->new IllegalArgumentException("Add this title to your library first"));i.setUserRating(r.rating());return dto(library.save(i));}
}